  id: ElementId;
  /** What kind it is. */
  kind: 'field' | 'richText' | 'plainText' | 'picture' | 'checkbox' | 'date' | 'dropDown' | 'comboBox' | 'group' | 'repeatingSection' | 'repeatingItem';
  /** A field's code. */
  code?: string;
  /** A control's tag. */
  tag?: string;
  /** A control's title. */
  title?: string;
  /** The result or content text, up to 200 characters. */
  display: string;
  /** The story it is in. */
  story: 'body' | 'header' | 'footer' | 'footnote' | 'endnote' | 'textBox' | 'subTemplate';
  /** The sub-template whose body it is in, when `story` is `subTemplate`. */
